    "Use a valid HEX, RGB or HSL color, such as #4D6BFF.": "Utilitzeu un color HEX, RGB o HSL vàlid, com ara #4D6BFF.",
    "Use a valid whole number or Roman numeral between 1 and 3,999.": "Utilitzeu un nombre enter o un numeral romà vàlid entre 1 i 3.999.",
