    "Uses your browser’s time zone data, including daylight saving changes.": "Utilitza les dades del fus horari del navegador, inclosos els canvis d'horari d'estiu.",
    "Open a tool": "Obre una eina",
    "Calculate average": "Calcula la mitjana",
    "Generated locally with your browser's secure random generator.": "Generat localment amb el generador de nombres aleatoris segur del navegador.",
    "URL components": "Components de l'URL",
