    "of": "de",
    "Tool categories": "Categories d'eines",
    "Guides": "Guies",
    "Optimize PDF (keep text & layout)": "Optimitza el PDF (conserva el text i la disposició)",
    "Strong compression (pages become images)": "Compressió alta (les pàgines es converteixen en imatges)",
    "PDFs are processed on this device, never uploaded. Compression has no fixed file-size cap; available memory and browser support are the practical limits.": "Els PDF es processen en aquest dispositiu; no es pengen mai. La compressió no té un límit fix de mida del fitxer; els límits pràctics són la memòria disponible i la compatibilitat del navegador.",
    "Best first try: rewrites and recompresses PDF structure without turning pages into images. Text and layout usually remain, but not every special feature is guaranteed; editing a signed PDF may invalidate its signature. It may not get smaller.": "Prova-ho primer: reescriu i comprimeix l’estructura del PDF sense convertir les pàgines en imatges. Normalment conserva el text i la disposició, però no totes les funcions especials; editar un PDF signat pot invalidar la signatura i potser no redueix la mida.",
    "Review this before continuing": "Revisa-ho abans de continuar",
    "Every page is rebuilt as an image. Text will no longer be searchable or selectable; links, forms, annotations, accessibility structure and signatures will not be preserved. Small text or fine details may look worse, and the file can even grow. Always compare the result and keep your original.": "Cada pàgina es reconstrueix com una imatge. El text ja no es podrà cercar ni seleccionar; no es conservaran enllaços, formularis, anotacions, accessibilitat ni signatures. Els detalls petits poden empitjorar i el fitxer pot créixer. Compara el resultat i conserva l’original.",
    "I understand these trade-offs and will keep the original.": "Entenc aquests compromisos i conservaré l’original.",
    "Image quality": "Qualitat de la imatge",
    "Balanced · clearer text": "Equilibrada · text més clar",
    "Smaller file · lower detail": "Fitxer més petit · menys detall",
    "Cancel": "Cancel·la",
    "PDF compression canceled. No new file was saved.": "S'ha cancel·lat la compressió del PDF. No s'ha desat cap fitxer nou.",
    "Optimizing PDF structure on your device…": "S'està optimitzant l'estructura del PDF al dispositiu...",
    "Rendering page {current} of {total} on your device…": "S'està processant la pàgina {current} de {total} al dispositiu...",
    "Creating the compressed PDF on your device…": "S'està creant el PDF comprimit al dispositiu...",
    "This method did not make the PDF smaller. The original is unchanged. Try the other mode.": "Aquest mètode no ha reduït la mida del PDF. L'original no ha canviat. Proveu l'altre mode.",
    "PDF optimization made the file {size} smaller. Compare it before using it. Your original is unchanged.": "L'optimització del PDF ha reduït la mida del fitxer {size}. Compareu-lo abans d'utilitzar-lo. L'original no ha canviat.",
    "Image compression made the file {size} smaller. Inspect readability; the original is unchanged.": "La compressió d'imatges ha reduït la mida del fitxer {size}. Comproveu-ne la llegibilitat; l'original no ha canviat.",
    "Choose a video": "Trieu un vídeo",
    "The video is processed on your device and is never uploaded. There is no fixed file-size cap; available memory, storage and browser codecs set practical limits.": "El vídeo es processa al dispositiu i no es penja mai a la xarxa. No hi ha un límit fix de mida del fitxer; la memòria disponible, l'espai d'emmagatzematge i els còdecs del navegador en determinen els límits pràctics.",
    "MP4 · broadly compatible": "MP4 · àmpliament compatible",
    "WebM · open format": "WebM · format obert",
    "Quality": "Qualitat",
    "Higher quality · larger file": "Qualitat superior · fitxer més gran",
    "Balanced": "Equilibrat",
    "Smaller file · more quality loss": "Fitxer més petit · més pèrdua de qualitat",
    "Maximum resolution": "Resolució màxima",
    "Keep original resolution": "Mantén la resolució original",
    "Up to 1080p": "Fins a 1080p",
    "Up to 720p": "Fins a 720p",
    "Before you start": "Abans de començar",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "La compressió recodifica el vídeo i pot reduir-ne la qualitat. Si un format no pot conservar una pista d'àudio, de subtítols o de dades, el procés s'atura en lloc d'eliminar-la silenciosament. El fitxer original no es modifica mai.",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "Aquest navegador no pot desar el resultat com a flux de dades, per la qual cosa utilitzarà temporalment la memòria del dispositiu. Els vídeos molt grans poden superar la capacitat del navegador o del dispositiu.",
    "Compress video": "Comprimeix el vídeo",
    "Video compression progress": "Progrés de la compressió del vídeo",
    "No upload. Keep this tab open while your device works.": "No cal carregar el fitxer. Mantén aquesta pestanya oberta mentre el dispositiu treballa.",
    "Video selected. Choose quality and resolution, then compress.": "Vídeo seleccionat. Tria la qualitat i la resolució i, a continuació, comprimeix-lo.",
    "Choose a video before compressing.": "Tria un vídeo abans de comprimir-lo.",
    "Choose where to save the new video…": "Tria on desar el vídeo nou...",
    "Encoding video on your device. Keep this tab open…": "Codificant el vídeo al dispositiu. Manteniu oberta aquesta pestanya...",
    "Compressing video: {percent}%": "Comprimint el vídeo: {percent}%",
    "Video saved as a new file, {size} smaller. Your original is unchanged.": "Vídeo desat com a fitxer nou, {size} més petit. El fitxer original no s'ha modificat.",
    "Compressed video is {size} smaller. Review it before sharing; your original is unchanged.": "El vídeo comprimit és {size} més petit. Reviseu-lo abans de compartir-lo; el fitxer original no s'ha modificat.",
    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "No s'ha pogut reduir la mida d'aquest vídeo. No se n'ha desat cap còpia; el fitxer original no s'ha modificat. Proveu amb una qualitat o resolució inferiors.",
    "Video compression canceled. No compressed copy was kept.": "Compressió del vídeo cancel·lada. No s'ha conservat cap còpia comprimida.",
    "Save was canceled. Your original video is unchanged.": "S'ha cancel·lat l'operació de desar. El vídeo original no s'ha modificat.",
    "This video has an audio, subtitle or data track that the selected format cannot keep. No output was saved.": "Aquest vídeo conté una pista d'àudio, de subtítols o de dades que el format seleccionat no pot conservar. No s'ha desat cap resultat.",
    "No video track was found in this file.": "No s'ha trobat cap pista de vídeo en aquest fitxer.",
    "This browser cannot encode the selected video in that format. Try another format or browser.": "Aquest navegador no pot codificar el vídeo seleccionat en aquest format. Proveu un altre format o navegador.",
    "This browser could not process this video. Try MP4 or WebM, another output format, or a smaller resolution.": "Aquest navegador no ha pogut processar el vídeo. Proveu amb MP4 o WebM, un altre format de sortida o una resolució més baixa.",
