    "Select an area in the preview.": "Selecciona una àrea a la previsualització.",
    "Select a larger area to replace.": "Seleccioneu una àrea més gran per substituir-la.",
    "Area selected. Choose a replacement and apply it.": "Àrea seleccionada. Trieu un element de substitució i apliqueu-lo.",
    "Replacement added. The page will be flattened when saved.": "S’ha afegit la substitució. La pàgina s’aplanarà quan es desi.",
    "PDF to Word · text only": "PDF a Word · només text",
