    "PowerPoint to PDF · print view": "PowerPoint a PDF · vista d’impressió",
    "Choose a file": "Tria un fitxer",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Els fitxers d'Office romanen al vostre dispositiu. El disseny, les fórmules, els gràfics, les animacions, els tipus de lletra i els salts de pàgina poden variar. La funció \"Office a PDF\" obre el diàleg d'impressió del navegador. Utilitzeu un ordinador per a fitxers grans.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "La conversió de PDF a Excel estima les files a partir del text seleccionable; no recrea fórmules ni taules. La conversió de PDF a PowerPoint crea diapositives que només contenen imatges. Els PDF escanejats requereixen un procés d'OCR previ.",
    "Office print view opened. Check it, then choose Save as PDF in the browser.": "S'ha obert la vista prèvia d'impressió d'Office. Reviseu-la i seleccioneu l'opció \"Desa com a PDF\" al navegador.",
    "The converted file is ready. Review the result and keep the original.": "El fitxer convertit ja està a punt. Reviseu el resultat i conserveu l'original.",
    "Processing PDF page": "S’està processant la pàgina PDF",
