      "description": "Aprèn la fórmula de la nota ponderada, calcula la nota actual d'una assignatura amb categories pendents i determina la puntuació d'examen necessària per assolir un objectiu.",
      "toolCta": "Calcula una nota ponderada o esbrina quina puntuació necessites a l'examen final.",
      "intro": "Una nota ponderada assigna a cada tasca o categoria la proporció de la nota final que s'indica al pla docent. Aquesta guia explica el càlcul, com gestionar una assignatura en curs i com calcular la puntuació necessària a partir d'una nota objectiu.",
      "sections": [
        {
          "heading": "Comença pels criteris d'avaluació del pla docent.",
          "blocks": [
            {
              "type": "p",
              "text": "Anota cada categoria, el seu pes i el percentatge que has obtingut en aquesta categoria. Utilitza els percentatges de les categories, no les puntuacions absolutes, quan les categories tinguin totals de punts diferents. Les dades de partida són una mitjana de deures del 90% i una mitjana d'exàmens del 80%; el nombre de preguntes dels deures no constitueix un pes per si mateix, tret que el pla docent indiqui el contrari."
            },
            {
              "type": "note",
              "title": "Comprova primer els pesos",
              "text": "En un curs finalitzat, els pesos de les categories solen sumar un 100%. Si el registre de qualificacions utilitza un total acumulat o algunes categories encara no tenen notes, la qualificació actual que es mostra es pot normalitzar en funció de la feina completada. Segueix les normes del pla docent o del registre de qualificacions."
            }
          ]
        },
        {
          "heading": "Utilitza la fórmula de la mitjana ponderada",
          "blocks": [
            {
              "type": "formula",
              "label": "Qualificació final del curs",
              "value": "grade₁ × weight₁ + grade₂ × weight₂ + …"
            },
            {
              "type": "p",
              "text": "Converteix els pesos percentuals en decimals abans de multiplicar. Per exemple, el 30% passa a ser 0,30. Si els deures tenen una puntuació del 92% i un pes del 40%, i els exàmens tenen una puntuació del 84% i un pes del 60%, el resultat és (92 × 0,40) + (84 × 0,60) = 87,2%."
            },
            {
              "type": "p",
              "text": "Si el pla docent expressa els pesos com a nombres enters, com ara 40 i 60, divideix la suma ponderada pel seu total: (92 × 40 + 84 × 60) ÷ 100 = 87,2%. Les dues formes són equivalents quan la suma dels pesos és 100."
            }
          ]
        },
        {
          "heading": "Calcula la qualificació actual quan algunes categories estan pendents de completar",
          "blocks": [
            {
              "type": "p",
              "text": "Quan només algunes categories tenen qualificacions, divideix els seus punts ponderats per la suma dels pesos de les categories que tenen qualificacions. Suposem que els deures tenen una puntuació del 92% i representen el 40% del curs, i que l'examen parcial té una puntuació del 84% i representa el 35%; l'examen final encara no s'ha corregit."
            },
            {
              "type": "formula",
              "label": "Nota actual basada en la feina feta",
              "value": "(92 × 0.40 + 84 × 0.35) ÷ (0.40 + 0.35) = 88.27%"
            },
            {
              "type": "p",
              "text": "Aquest 88,27% fa referència només a les categories completades. No és el mateix que els punts ja obtinguts per a la nota final del curs, que són 66,2 punts percentuals abans de comptabilitzar el 25% restant."
            }
          ]
        },
        {
          "heading": "Calcula la nota que necessites a l'examen final",
          "blocks": [
            {
              "type": "p",
              "text": "Si la teva nota actual reflecteix tota la feina feta excepte l'examen final, utilitza el pes que té aquest examen en la nota global del curs per calcular la nota que et falta."
            },
            {
              "type": "formula",
              "label": "Nota necessària a l'examen final",
              "value": "(target grade − current grade × (1 − final weight)) ÷ final weight"
            },
            {
              "type": "p",
              "text": "Exemple: la teva nota actual és del 88%, l'examen final val un 30% i el teu objectiu és un 90%. El càlcul és (90 − 88 × 0,70) ÷ 0,30 = 94,67%. Necessitaries aproximadament un 94,7% a l'examen final, sempre que la nota actual cobreixi exactament l'altre 70%."
            },
            {
              "type": "note",
              "title": "Si el resultat supera el 100%",
              "text": "L'objectiu és matemàticament inabastable sota aquestes premisses. Si la xifra és inferior al 0%, la teva feina actual ja supera l'objectiu matemàticament. Els punts addicionals, les puntuacions descartades, els ajustos de qualificació (corbes) i les regles de categoria poden modificar el resultat real."
            }
          ]
        },
        {
          "heading": "Errors habituals que cal evitar",
          "blocks": [
            {
              "type": "list",
              "items": [
                "Calcular la mitjana de les notes de les categories amb el mateix pes quan el pla d'estudis els assigna pesos diferents.",
                "Utilitzar les puntuacions brutes de tasques amb totals possibles diferents en lloc dels percentatges de categoria.",
                "Considerar el total acumulat actual del registre de notes com si ja inclogués totes les categories pendents de qualificació.",
                "Donar per fet que el càlcul de l'examen final té en compte els punts addicionals, els ajustos de qualificació, les proves descartades o les regles de nota mínima a l'examen sense consultar el pla d'estudis."
              ]
            },
            {
              "type": "p",
              "text": "Per fer una comprovació ràpida, introdueix les notes i els pesos a la calculadora gratuïta de mitjanes ponderades i notes finals. Funciona al navegador i no carrega les teves puntuacions al servidor."
            }
          ]
        }
      ],
      "sources": [
        {
          "label": "Northern Arizona University: Calculating weighted grades",
          "url": "https://www.cefns.nau.edu/~edo/Classes/HowtoCalcGrades.html"
        }
      ]
