                "Mantén cada resultat amb una amplada de quatre bits, incloent-hi els zeros.",
                "Separa els grups amb espais per comprovar la feina; elimina els espais només si la destinació requereix una cadena contínua.",
                "Si l'entrada inclou un prefix com ara 0x, elimineu-lo abans d'introduir els dígits en un convertidor que només espera el valor."
